import { isEmpty } from "lodash";
import { z } from "zod";

import { messagingSdkClient } from "@/server/libs/messaging-sdk-client";

import { organizationMemberProcedure } from "../procedures/organization-member-procedure";
import { router } from "../trpc";

// Input schemas based on the generated types
const participantInputSchema = z.object({
  first_name: z.string(),
  last_name: z.string(),
  email: z.string().email(),
  phone: z.string(),
  timezone: z.string().optional(),
});

const timeSlotInputSchema = z.object({
  start_time: z.string(),
  end_time: z.string(),
});

export const availabilityRouter = router({
  getParticipants: organizationMemberProcedure
    .input(
      z.object({
        page: z.number().int().positive().optional().default(1),
        page_size: z.number().int().positive().max(100).optional().default(20),
        search: z.string().optional(),
        has_availability: z.boolean().optional(),
      }),
    )
    .query(async ({ input }) => {
      const { organizationId, page, page_size, search, has_availability } =
        input;

      const {
        getParticipantsWithAvailabilityOrganizationsOrgIdParticipantsGet,
      } = await import("@purplefish-ai/messaging-api-client");
      const response =
        await getParticipantsWithAvailabilityOrganizationsOrgIdParticipantsGet({
          client: messagingSdkClient,
          path: {
            org_id: organizationId,
          },
          query: {
            page,
            page_size,
            ...(search && { search }),
            ...(has_availability !== undefined && { has_availability }),
          },
        });

      if (isEmpty(response.data)) {
        console.error("Failed to fetch participants:", response.error);
        throw new Error("Failed to fetch participants");
      }

      return response.data as Record<string, unknown>;
    }),

  bulkCreateParticipants: organizationMemberProcedure
    .input(
      z.object({
        participants: z.array(participantInputSchema),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, participants } = input;

      const { bulkCreateParticipantsOrganizationsOrgIdParticipantsPost } =
        await import("@purplefish-ai/messaging-api-client");
      const response =
        await bulkCreateParticipantsOrganizationsOrgIdParticipantsPost({
          client: messagingSdkClient,
          path: {
            org_id: organizationId,
          },
          body: {
            participants,
          },
        });

      if (isEmpty(response.data)) {
        console.error("Failed to create participants:", response.error);
        throw new Error("Failed to create participants");
      }

      return response.data as Record<string, unknown>;
    }),

  addAvailability: organizationMemberProcedure
    .input(
      z.object({
        participant_id: z.string(),
        time_slots: z.array(timeSlotInputSchema),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, participant_id, time_slots } = input;

      const {
        addAvailabilityForParticipantOrganizationsOrgIdParticipantsParticipantIdAvailabilityPost,
      } = await import("@purplefish-ai/messaging-api-client");
      const response =
        await addAvailabilityForParticipantOrganizationsOrgIdParticipantsParticipantIdAvailabilityPost(
          {
            client: messagingSdkClient,
            path: {
              org_id: organizationId,
              participant_id,
            },
            body: {
              time_slots,
            },
          },
        );

      if (isEmpty(response.data)) {
        console.error("Failed to add availability:", response.error);
        throw new Error("Failed to add availability");
      }

      return response.data as Record<string, unknown>;
    }),

  removeTimeslot: organizationMemberProcedure
    .input(
      z.object({
        participant_id: z.string(),
        timeslot_id: z.string(),
      }),
    )
    .mutation(async ({ input }) => {
      const { organizationId, participant_id, timeslot_id } = input;

      const {
        removeTimeslotForParticipantOrganizationsOrgIdParticipantsParticipantIdAvailabilityTimeslotIdDelete,
      } = await import("@purplefish-ai/messaging-api-client");
      const response =
        await removeTimeslotForParticipantOrganizationsOrgIdParticipantsParticipantIdAvailabilityTimeslotIdDelete(
          {
            client: messagingSdkClient,
            path: {
              org_id: organizationId,
              participant_id,
              timeslot_id,
            },
          },
        );

      if (isEmpty(response.data)) {
        console.error("Failed to remove timeslot:", response.error);
        throw new Error("Failed to remove timeslot");
      }

      return response.data as Record<string, unknown>;
    }),
});

"use client";

import { useRouter } from "@bprogress/next/app";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { z } from "zod";

import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import { Checkbox } from "@purplefish-ai/shadcn-ui/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@purplefish-ai/shadcn-ui/components/ui/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@purplefish-ai/shadcn-ui/components/ui/form";
import { Input } from "@purplefish-ai/shadcn-ui/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@purplefish-ai/shadcn-ui/components/ui/select";
import { toast } from "@purplefish-ai/shadcn-ui/components/ui/use-toast";

import { useTRPC } from "@/trpc/client";

const formSchema = z.object({
  first_name: z.string().min(1, "First name is required"),
  last_name: z.string().min(1, "Last name is required"),
  email: z.string().email("Invalid email address"),
  phone: z
    .string()
    .min(10, "Phone number must be at least 10 digits")
    .regex(/^\+?[\d\s()-]+$/, "Invalid phone number format")
    .refine(
      (val) => val.replace(/\D/g, "").length >= 10,
      "Phone number must contain at least 10 digits",
    ),
  timezone: z.string().min(1, "Timezone is required"),
  add_availability_now: z.boolean().default(false),
});

type FormData = z.infer<typeof formSchema>;

// Common timezones - in production, this would come from a comprehensive list
const TIMEZONES = [
  { value: "America/New_York", label: "Eastern Time (ET)" },
  { value: "America/Chicago", label: "Central Time (CT)" },
  { value: "America/Denver", label: "Mountain Time (MT)" },
  { value: "America/Los_Angeles", label: "Pacific Time (PT)" },
  { value: "America/Phoenix", label: "Arizona Time (AZ)" },
  { value: "Europe/London", label: "London (GMT)" },
  { value: "Europe/Paris", label: "Paris (CET)" },
  { value: "Asia/Tokyo", label: "Tokyo (JST)" },
  { value: "Asia/Shanghai", label: "Shanghai (CST)" },
  { value: "Australia/Sydney", label: "Sydney (AEDT)" },
];

interface AddExternalParticipantModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  organizationId: string;
  onParticipantAdded: () => void;
}

export function AddExternalParticipantModal({
  open,
  onOpenChange,
  organizationId,
  onParticipantAdded,
}: AddExternalParticipantModalProps) {
  const router = useRouter();
  const trpc = useTRPC();
  const form = useForm<FormData>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      first_name: "",
      last_name: "",
      email: "",
      phone: "",
      timezone: "America/New_York",
      add_availability_now: false,
    },
  });

  const createParticipantMutation = useMutation(
    trpc.availability.bulkCreateParticipants.mutationOptions({
      onSuccess: (data) => {
        // Check if participant was created successfully
        if (data.failed_count > 0 || data.results[0]?.success === false) {
          const error =
            data.results[0]?.error || "Failed to create participant";
          toast({
            title: "Error",
            description: error,
            variant: "destructive",
          });
          return;
        }

        const participant = data.results[0]?.participant;
        if (!participant) {
          toast({
            title: "Error",
            description: "Participant was created but data is missing.",
            variant: "destructive",
          });
          return;
        }

        const formData = form.getValues();
        toast({
          title: "Participant created",
          description: `${formData.first_name} ${formData.last_name} has been added successfully.`,
        });

        if (formData.add_availability_now && participant.participant_id) {
          // Navigate to the participant detail page to add availability
          router.push(
            `/organizations/${organizationId}/availability/${participant.participant_id}`,
          );
        } else {
          onParticipantAdded();
        }

        form.reset();
      },
      onError: (error) => {
        const message =
          error instanceof Error
            ? error.message
            : "Failed to create participant. Please try again.";
        toast({
          title: "Error",
          description: message,
          variant: "destructive",
        });
      },
    }),
  );

  const onSubmit = (data: FormData) => {
    createParticipantMutation.mutate({
      organizationId,
      participants: [
        {
          first_name: data.first_name,
          last_name: data.last_name,
          email: data.email,
          phone: data.phone,
          timezone: data.timezone,
        },
      ],
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Add External Participant</DialogTitle>
        </DialogHeader>

        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="first_name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>First Name*</FormLabel>
                    <FormControl>
                      <Input placeholder="John" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="last_name"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel>Last Name*</FormLabel>
                    <FormControl>
                      <Input placeholder="Doe" {...field} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Email*</FormLabel>
                  <FormControl>
                    <Input
                      type="email"
                      placeholder="john.doe@example.com"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="phone"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Phone*</FormLabel>
                  <FormControl>
                    <Input
                      type="tel"
                      placeholder="+1 (555) 123-4567"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="timezone"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Timezone*</FormLabel>
                  <Select
                    onValueChange={field.onChange}
                    defaultValue={field.value}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder="Select a timezone" />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {TIMEZONES.map((tz) => (
                        <SelectItem key={tz.value} value={tz.value}>
                          {tz.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="add_availability_now"
              render={({ field }) => (
                <FormItem className="flex flex-row items-start space-x-3 space-y-0">
                  <FormControl>
                    <Checkbox
                      checked={field.value}
                      onCheckedChange={field.onChange}
                    />
                  </FormControl>
                  <div className="space-y-1 leading-none">
                    <FormLabel>Add availability now</FormLabel>
                  </div>
                </FormItem>
              )}
            />

            <div className="flex justify-end gap-3 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => onOpenChange(false)}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={createParticipantMutation.isPending}
              >
                {createParticipantMutation.isPending ? "Creating..." : "Create"}
              </Button>
            </div>
          </form>
        </Form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";

import { useRouter } from "@bprogress/next/app";
import { useQuery } from "@tanstack/react-query";
import { useDebounce } from "use-debounce";

import IconAdd from "@purplefish-ai/material-icons/icons/icon-add";
import IconSearch from "@purplefish-ai/material-icons/icons/icon-search";
import { Button } from "@purplefish-ai/shadcn-ui/components/ui/button";
import { Input } from "@purplefish-ai/shadcn-ui/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@purplefish-ai/shadcn-ui/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@purplefish-ai/shadcn-ui/components/ui/table";

import { getFormattedPhoneNumber } from "@/common/libs/get-formatted-phone-number";
import { useTRPC } from "@/trpc/client";

import { AddExternalParticipantModal } from "./add-external-participant-modal";

interface AvailabilityListContentProps {
  organizationId: string;
}

export function AvailabilityListContent({
  organizationId,
}: AvailabilityListContentProps) {
  const router = useRouter();
  const trpc = useTRPC();
  const [searchQuery, setSearchQuery] = useState("");
  const [hasAvailabilityFilter, setHasAvailabilityFilter] = useState<
    "all" | "has" | "none"
  >("all");
  const [currentPage, setCurrentPage] = useState(1);
  const [isAddParticipantOpen, setIsAddParticipantOpen] = useState(false);

  const [debouncedSearchQuery] = useDebounce(searchQuery, 300);
  const pageSize = 20;

  // Reset pagination when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [debouncedSearchQuery, hasAvailabilityFilter]);

  const { data, isLoading, refetch } = useQuery(
    trpc.availability.getParticipants.queryOptions({
      organizationId,
      page: currentPage,
      page_size: pageSize,
      search: debouncedSearchQuery || undefined,
      has_availability:
        hasAvailabilityFilter === "has"
          ? true
          : hasAvailabilityFilter === "none"
            ? false
            : undefined,
    }),
  );

  const handleViewParticipant = useCallback(
    (participantId: string) => {
      router.push(
        `/organizations/${organizationId}/availability/${participantId}`,
      );
    },
    [organizationId, router],
  );

  const handleParticipantAdded = useCallback(() => {
    setIsAddParticipantOpen(false);
    void refetch();
  }, [refetch]);

  // Use data directly from server since filtering is done server-side
  const filteredParticipants = data?.participants ?? [];

  const totalPages = data?.pagination ? data.pagination.total_pages : 1;

  return (
    <>
      <div className="space-y-4">
        {/* Filters */}
        <div className="flex flex-wrap gap-4">
          <div className="min-w-[200px] flex-1">
            <div className="relative">
              <IconSearch className="text-muted-foreground absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2" />
              <Input
                placeholder="Search by name or email..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10"
              />
            </div>
          </div>

          <Select
            value={hasAvailabilityFilter}
            onValueChange={(value: "all" | "has" | "none") =>
              setHasAvailabilityFilter(value)
            }
          >
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Filter by availability" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Participants</SelectItem>
              <SelectItem value="has">Has Availability</SelectItem>
              <SelectItem value="none">No Availability</SelectItem>
            </SelectContent>
          </Select>

          <Button
            onClick={() => setIsAddParticipantOpen(true)}
            className="gap-2"
          >
            <IconAdd className="h-4 w-4" />
            Add External Participant
          </Button>
        </div>

        {/* Table */}
        <div className="rounded-lg border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Email</TableHead>
                <TableHead>Phone</TableHead>
                <TableHead className="text-center">Available Slots</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell colSpan={5} className="py-8 text-center">
                    Loading participants...
                  </TableCell>
                </TableRow>
              ) : filteredParticipants.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={5} className="py-8 text-center">
                    No participants found
                  </TableCell>
                </TableRow>
              ) : (
                filteredParticipants.map((participant) => (
                  <TableRow key={participant.participant_id}>
                    <TableCell className="font-medium">
                      {participant.first_name} {participant.last_name}
                    </TableCell>
                    <TableCell>{participant.email}</TableCell>
                    <TableCell>
                      {participant.phone
                        ? getFormattedPhoneNumber(participant.phone)
                        : "-"}
                    </TableCell>
                    <TableCell className="text-center">
                      {participant.availability.length}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() =>
                          handleViewParticipant(participant.participant_id)
                        }
                      >
                        View
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between">
            <p className="text-muted-foreground text-sm">
              Page {currentPage} of {totalPages}
            </p>
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                disabled={currentPage === 1}
              >
                Previous
              </Button>
              <Button
                variant="outline"
                size="sm"
                onClick={() =>
                  setCurrentPage((p) => Math.min(totalPages, p + 1))
                }
                disabled={currentPage === totalPages}
              >
                Next
              </Button>
            </div>
          </div>
        )}
      </div>

      <AddExternalParticipantModal
        open={isAddParticipantOpen}
        onOpenChange={setIsAddParticipantOpen}
        organizationId={organizationId}
        onParticipantAdded={handleParticipantAdded}
      />
    </>
  );
}

